import {calendarEvent} from './calendar.js';
import {canMeetExtra,EXTRA_CAST} from './extended-cast.js';
import {planOptionGroups} from './plan-options.js';
import {roadmapView} from './plan-roadmap.js';
import {relationshipSignal} from './relationship-events.js';
import {sceneAsset,seasonForMonth,SEASONS,eventLocation} from './scenery.js';
import {PLAN_STEPS,planOptions,planAnswerLabel,planChoiceHint,planAnswerValues,planSelectionHint} from './startup-plan.js';
import {getPortrait,effectsText} from './engine.js';
import {choicesWithPermanentLast,choiceAvailability} from './conditions.js';
import {availablePeople,scenePerson,groupAdvice,sceneReadings,relationshipLabel,relationshipMeter} from './story-engine.js';
import {statIcon,brandMark,permanentLockMessage} from './stat-view.js';
export {wikiView,wikiCards,termDetail} from './wiki-view.js';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const image=p=>`<img src="assets/${p.file}" alt="${esc(p.name+' · '+p.role)}" loading="lazy">`;

export function initialPlanView(state,data){
 const p=state.initialPlan,step=PLAN_STEPS[p.step],answer=p.answers[step.key],selected=planAnswerValues(answer),allSelected=Object.keys(planOptions(step,data,state.industry)).every(id=>selected.includes(id)),hint=state.planBeforeEdit?'':planSelectionHint(state,step.key);
 return `<header class="topbar plan-topbar"><button type="button" class="brand brand-home" data-action="intro" aria-label="모두의 창업 첫 화면으로">${brandMark()}<div><strong>모두의 창업</strong><span>CEO로 살아남기</span></div></button><div class="topactions"><button class="quiet" data-action="slots">이어하기</button></div></header><main class="plan-shell"><div class="plan-page-heading"><div><h1>${state.planBeforeEdit?'계획서 수정':'초기 계획서'}</h1><span>${esc(state.name)} · ${esc(data.industries[state.industry].label)}</span></div>${state.planBeforeEdit?'<button class="quiet" data-action="plan-edit-cancel">수정 취소</button>':''}<button class="quiet" data-action="plan-random-all">전체 무작위 선택</button></div><section class="memo-sheet" aria-labelledby="plan-question"><div class="memo-binding" aria-hidden="true"></div><div class="memo-progress"><span>${step.label}</span><span>${p.step+1} / ${PLAN_STEPS.length}</span></div><div class="memo-progress-track"><i style="width:${(p.step+1)/PLAN_STEPS.length*100}%"></i></div><div class="memo-question-row"><h2 id="plan-question">${step.ask}</h2><div class="memo-selection-tools"><span>복수 선택 가능</span><button class="quiet" data-action="plan-select-all">${allSelected?'전체 해제':'전체 선택'}</button></div></div>${planOptionGroups(step,data,state.industry).map(group=>`<div class="memo-group">${group.label?`<h3>${group.label}</h3>`:''}<div class="memo-options" role="group" aria-label="${esc(group.label||step.label)} 복수 선택">${group.entries.map(([key,label])=>`<button class="memo-option ${selected.includes(key)?'selected':''}" data-action="plan-option" data-id="${key}" aria-pressed="${selected.includes(key)}"><span>${esc(label)}</span>${!state.planBeforeEdit&&planChoiceHint(step.key,key)?`<small>${planChoiceHint(step.key,key)}</small>`:''}${selected.includes(key)?statIcon('check'):''}</button>`).join('')}</div></div>`).join('')}${hint?`<p class="memo-selection-hint" role="status">${hint}</p>`:''}<div class="memo-navigation"><button class="quiet" data-action="plan-back" ${p.step===0?'disabled':''}>이전</button><div><button class="quiet" data-action="plan-random">임의로 정하기</button><button class="primary" data-action="plan-next">${p.step===PLAN_STEPS.length-1?'실행 계획 만들기':'다음'}</button></div></div></section><div class="plan-step-list" aria-label="계획서 항목">${PLAN_STEPS.map((s,i)=>`<span class="${i===p.step?'current':p.answers[s.key]?'written':''}">${p.answers[s.key]?'✓ ':''}${s.label}</span>`).join('')}</div></main>`;
}
export function planReview(state,data){return `${roadmapView(state)}<h3 class="plan-original-heading">${state.planRevisions?.length?'수정한 계획의 선택':'처음 선택한 내용'}</h3><div class="plan-review">${PLAN_STEPS.map(step=>`<div><span>${step.label}</span><strong>${esc(planAnswerLabel(state,step,data))}</strong></div>`).join('')}</div>`;}
function sceneGuide(phase){return `<aside class="scene-guide"><img src="assets/npc-ai_agent.png" alt="안내 비서 모아"><p><b>모아</b> ${['선택지 아래의 예상 변화를 비교해 보세요. 하나를 고른 뒤 조언을 듣고 최종 결정할 수 있어요.','확정할 선택을 확인하고 한 의견을 골라 주세요. 그 의견을 낸 사람 모두의 호감도가 올라요.','이번 선택이 남긴 변화와 배움을 확인해 보세요. 읽기를 마치면 계속하기로 돌아갈 수 있어요.'][phase]}</p></aside>`;}
function phaseStrip(current){return `<div class="scene-phases" aria-label="이야기 진행">${['사건','조언','결과'].map((x,i)=>`<span class="${current===i?'active':''}">${x}</span>`).join('')}</div>`;}
function sceneStage(person,speaker,line,state,stance=''){
 const place=eventLocation(state),season=seasonForMonth(state.month);
 return `<div class="vn-stage" data-season="${season}"><img class="vn-backdrop-art" src="${sceneAsset(place,state.month)}" alt="${SEASONS[season]}의 대화 배경"><div class="vn-character">${image(person)}</div><div class="vn-dialogue"><span class="vn-name">${esc(person.name)} <small>${esc(speaker||person.role)}</small>${stance?`<b class="stance-badge" data-stance="${stance}">${stance}</b>`:''}</span><p>${esc(line)}</p></div></div>`;
}
export function eventScene(state,data){
 const e=state.pending,story=data.story,person=scenePerson(state,story);
 if(e.phase==='advice'){
  const groups=groupAdvice(state,story);
  const cards=groups.map(({stance,members,index})=>`<article class="opinion-card" data-stance="${stance}"><header><h3>${stance}</h3><span>${members.length}명</span></header>${members.length?`<ul>${members.map(({person,line})=>`<li><span class="adviser-mini">${image(person)}</span><div><b>${esc(person.name)}</b> <small>${esc(person.role)}</small><p>${esc(line)}</p></div></li>`).join('')}</ul><div class="opinion-outcome"><small>확정할 선택</small><strong>${esc(e.choices[index].label)}</strong></div><button class="primary" data-action="advice-follow" data-id="${stance}" aria-label="${stance} 의견으로 최종 결정">${stance} 의견 선택</button>`:'<p>이 의견을 낸 인물이 없어요.</p>'}</article>`).join('');
  return {title:e.title,body:`${phaseStrip(1)}${sceneGuide(1)}<p class="provisional-choice"><span>먼저 고른 선택</span>${esc(e.choices[e.selectedChoice].label)}</p><div class="opinion-grid">${cards}</div><details class="advice-reading"><summary>관련 아침편지 읽기</summary>${readingCards(sceneReadings(e.id,story,e.card,data))}</details><div class="scene-footer"><button class="quiet" data-action="advice-back">선택지 다시 보기</button>${groups.every(g=>!g.members.length)?'<button class="primary" data-action="advice-self">내 판단대로 결정</button>':''}</div>`};

 }
 const opening=story.openings[e.id];
 const calendar=e.calendar?calendarEvent({...state,ending:null,month:e.calendar.elapsed,seenEvents:(state.seenEvents||[]).filter(id=>id!==e.id)}):null;
 const text=opening?.line||calendar?.text||e.text;
 return {title:e.title,body:`${e.relationship?`<p class="relationship-trigger ${e.relationship.tone}">관계 사건 · 호감도 ${e.relationship.value}에서 시작</p>`:''}${phaseStrip(0)}${sceneGuide(0)}${sceneStage(person,person.role,text,state)}${opening?`<p class="scene-context">${esc(e.text)}</p>`:''}<div class="scene-choices">${choicesWithPermanentLast(state,e.choices,e.req).map(({choice:c,index,permanent})=>{const status=choiceAvailability(state,c);return `<div class="event-option ${permanent?'is-permanent':''}"><button class="event-choice" data-action="choose-event" data-index="${index}" ${status.ok?'':'disabled'}><strong>${esc(c.label)}</strong>${status.ok?'':`<small>${esc(status.reasons.join(' · '))}</small>`}</button>${permanent?permanentLockMessage():''}<div class="scene-effects"><span>예상 변화</span><p>${esc(effectsText(c.fx)||c.hint||'선택 후 결과 확인')}${c.later?.length?' · 후속 사건 있음':''}</p></div></div>`;}).join('')}</div>`};
}
export function readingCards(readings){return `<section class="letter-examples"><div class="letter-heading">${statIcon('book')}<h3>그만의 아침편지</h3></div>${readings.map(r=>`<article><span>${r.kind==='letter'?'아침편지':r.kind==='video'?'영상 주제':'창업 FAQ'}</span><h4>${esc(r.title)}</h4>${r.gist?`<p>${esc(r.gist)}</p>`:''}<button class="reading-link" data-action="reading" data-id="${esc(r.id)}">이 안에서 읽기 ${statIcon('book')}</button></article>`).join('')}<small>명승은 · 관련 글과 게임 학습 노트</small></section>`;}
export function resultScene(state,data){
 const r=state.lastScene,lesson=data.lessons.find(l=>l.id===r.card),person=data.story.cast.find(p=>p.id===r.adviser);
 return {title:'선택의 결과',body:`${phaseStrip(2)}${sceneGuide(2)}<div class="scene-result"><span class="result-kicker">${esc(r.title)}</span><h3>${esc(r.choice)}</h3><p>${esc(r.text)}</p><span class="followed-advice">${r.stance?`${esc(r.stance)} 의견을 선택했어요`:person?`${esc(person.name)}의 조언을 따랐어요`:'내 판단으로 결정했어요'}</span>${effectsText(r.fx)?`<div class="scene-result-fx">${esc(effectsText(r.fx))}</div>`:''}</div>${lesson?`<article class="earned-lesson" data-area="${esc(lesson.area)}"><span>${statIcon('book')} ${r.newLesson?'배움 카드 획득':'배움 카드'} · ${esc(lesson.area)}</span><h3>${esc(lesson.title)}</h3><p>${esc(lesson.body)}</p></article>`:''}${(r.relationships||(r.relationship?[r.relationship]:[])).map(v=>`<p class="relationship-result">${esc(v.name)} 호감도 ${v.before} → ${v.after}</p>`).join('')}${readingCards(sceneReadings(r.eventId,data.story,r.card,data))}<div class="modal-actions"><button class="primary" data-action="scene-done">${state.ending?'엔딩 보기':'계속하기'}</button></div>`};
}
export function peopleView(state,data){
 const active=availablePeople(state,data.story),known=new Set([...(state.metPeople||[]),...active.map(p=>p.id)]);
 return `<div class="people-caption"><span>${known.size} / ${data.story.cast.length}명</span><button class="quiet" data-action="initial-plan">초기 계획서</button></div><div class="people-grid">${data.story.cast.map(p=>{const met=known.has(p.id),meet=EXTRA_CAST.some(x=>x.id===p.id)&&canMeetExtra(state,p.id)&&!state.seats?.[p.id],count=(state.adviceHistory||[]).filter(h=>h.role===p.id||h.roles?.includes(p.id)).length,value=state.relations?.[p.id]??15;return `<article class="card person-card ${met?'':'not-met'}"><div class="person-photo">${met?image(p):`<div class="unknown-person">${statIcon('person')}</div>`}<span>${esc(p.role)}</span></div><div class="person-info"><h2>${met?esc(p.name):'아직 만나지 못했어요'}</h2>${met?`<p>${esc(p.bio)}</p><div class="relationship-row"><span>${relationshipLabel(value)}</span><b>${value}</b></div><div class="relationship-bar"><i style="width:${relationshipMeter(value)}%"></i></div><div class="person-card-foot"><span>따른 조언 ${count}회</span>${meet?`<button class="quiet" data-action="meet-person" data-id="${p.id}" ${state.pending||state.lastScene?.unread||state.ending?'disabled':''}>함께하기</button>`:''}<button class="quiet" data-action="person" data-id="${p.id}">기록 보기</button></div>`:`<p>${esc(data.story.peopleUnlock[p.id]||({customer:'첫 고객을 만나면 알게 돼요',partner:'배우자가 있거나 사건에서 만나면 알게 돼요'}[p.id])||'이야기를 진행하며 만날 수 있어요')}</p>${meet?`<button class="quiet" data-action="meet-person" data-id="${p.id}" ${state.pending||state.lastScene?.unread||state.ending?'disabled':''}>만나기</button>`:''}`}</div></article>`;}).join('')}</div>`;
}
export function personDetail(state,data,id){
 const person=data.story.cast.find(p=>p.id===id);if(!person)return null;
 const records=(state.adviceHistory||[]).filter(x=>x.role===id||x.roles?.includes(id));
 return {title:person.name,body:`<div class="person-detail"><div class="person-detail-art">${image(person)}</div><div><span class="tag">${esc(person.role)}</span><p>${esc(person.bio)}</p><strong>${esc(person.focus)}</strong></div></div><h3 class="person-record-title">함께한 선택</h3><div class="person-records">${records.length?records.map(r=>`<article><small>${r.month}개월 차</small><h4>${esc(r.title)}</h4><p>${esc(r.choice)}</p></article>`).join(''):'<p>아직 따른 조언이 없어요.</p>'}</div>`};
}
